<?php declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM inventario WHERE id=?');$s->execute([$id]);$item=$s->fetch();if(!$item){http_response_code(404);exit('Artículo no encontrado');}$s=$pdo->prepare('SELECT * FROM movimientos_inventario WHERE inventario_id=? ORDER BY id DESC LIMIT 500');$s->execute([$id]);$rows=$s->fetchAll();?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Movimientos · SRNU</title><?=srnu_ui_head()?></head><body><?php srnu_appbar('inventario');?><main class="w"><div class="srnu-page-heading"><div><h1><?=eh($item['nombre'])?></h1><p>Movimientos de inventario · Stock actual <?=number_format((float)$item['stock'],3)?></p></div><a class="btn light" href="inventario.php">← Inventario</a></div><section class="tablebox"><table><thead><tr><th>Fecha</th><th>Tipo</th><th>Cantidad</th><th>Costo</th><th>Referencia</th><th>Notas</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=eh($r['created_at'])?></td><td><?=eh($r['tipo'])?></td><td><?=number_format((float)$r['cantidad'],3)?></td><td><?=emoney($r['costo_unitario'])?></td><td><?=eh($r['referencia_tipo'])?> <?=eh($r['referencia_id'])?></td><td><?=eh($r['notas'])?></td></tr><?php endforeach;?></tbody></table></section></main></body></html>
